 13	
 14	/**
 15	 * Build a minimal ErrorLogManager stub backed by an in-memory entry array.
 16	 * Only `list()` is implemented (append, getById, clear, sources are no-ops).
 17	 */
 18	function makeMockErrorLogManager(entries: ErrorLogEntry[]): ErrorLogManager {
 19	    return {
 20	        append: () => entries[0]!,
 21	        list: (options?: ErrorLogListOptions): ErrorLogListResult => {
 22	            let filtered = [...entries].reverse(); // newest-first
 23	            if (options?.source !== undefined) {
 24	                filtered = filtered.filter((e) => e.Source === options.source);
 25	            }
 26	            const total = filtered.length;
 27	            return { entries: filtered, total };
 28	        },
 29	        getById: (id: number) => entries.find((e) => e.Id === id),
 30	        clear: () => {},
 31	        sources: () => [],
 32	    } as unknown as ErrorLogManager;
 33	}
