  1	/**
  2	 * Integration tests for:
  3	 *   GET  /api/projects/:id/workspaces/:wid/health
  4	 *   POST /api/projects/:id/workspaces/:wid/regenerate-workspace-file
  5	 *
  6	 * These tests exercise the full request pipeline through the Router and route
  7	 * handlers using lightweight mock managers.  The health and regenerate routes
  8	 * both perform real `fs` operations, so a temporary directory is created on
  9	 * disk for every on-disk scenario and cleaned up after each test.
 10	 *
 11	 * @see src/server/routes/workspaces.ts — route handler implementations
 12	 * @see src/orchestration/workspace-health.ts — WorkspaceHealthReport type and checkWorkspaceHealth()
 13	 */
 14	import { test, after } from 'node:test';
 15	import assert from 'node:assert/strict';
 16	import * as fs from 'node:fs';
 17	import * as path from 'node:path';
 18	import * as os from 'node:os';
 19	import { Router } from '../../router.js';
 20	import { registerWorkspaceRoutes } from '../../routes/workspaces.js';
 21	import { NotFoundError } from '../../../errors.js';
 22	import type { WorkspaceInfo } from '../../../models/workspace/workspace.types.js';
 23	import type { ProjectData } from '../../../models/project/project.types.js';
 24	import type { WorkspaceHealthReport } from '../../../orchestration/workspace-health.js';
 25	import { mockRequest, mockResponse, type MockResponse } from '../helpers/mock-http.js';
 26	
 27	// ---------------------------------------------------------------------------
 28	// Temp-directory lifecycle
 29	// ---------------------------------------------------------------------------
 30	
 31	// Track every directory created during this test module so they are always
 32	// removed — both in the normal flow (after()) and on crash (process.on('exit')).
 33	const allTempDirs: string[] = [];
 34	
 35	process.on('exit', () => {
 36	    for (const dir of allTempDirs) {
 37	        try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* best-effort */ }
 38	    }
 39	});
 40	
 41	after(() => {
 42	    for (const dir of allTempDirs) {
 43	        try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* best-effort */ }
 44	    }
 45	    allTempDirs.length = 0;
 46	});
 47	
 48	/**
 49	 * Creates a unique temporary directory, registers it for cleanup, and
 50	 * returns its absolute path.
 51	 */
 52	function makeTempDir(): string {
 53	    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ws-health-test-'));
 54	    allTempDirs.push(dir);
 55	    return dir;
 56	}
