 58	// ---------------------------------------------------------------------------
 59	// Mock WorkspaceManager
 60	// ---------------------------------------------------------------------------
 61	
 62	class MockWorkspaceManager {
 63	    private readonly data = new Map<string, Map<string, WorkspaceInfo>>();
 64	
 65	    /**
 66	     * Seeds a workspace entry so the mock returns it from `getById`.
 67	     */
 68	    seed(projectId: string, workspaceId: string): void {
 69	        const now = new Date().toISOString();
 70	        if (!this.data.has(projectId)) {
 71	            this.data.set(projectId, new Map());
 72	        }
 73	        this.data.get(projectId)!.set(workspaceId, {
 74	            ProjectID: projectId,
 75	            WorkspaceID: workspaceId,
 76	            Description: '',
 77	            DateCreated: now,
 78	            DateModified: now,
 79	            Notes: '',
 80	        });
 81	    }
 82	
 83	    getById(projectId: string, workspaceId: string): WorkspaceInfo | undefined {
 84	        const project = this.data.get(projectId);
 85	        if (!project) {
 86	            throw new NotFoundError(`Cannot get workspace: project "${projectId}" does not exist.`);
 87	        }
 88	        return project.get(workspaceId);
 89	    }
 90	}
