 92	// ---------------------------------------------------------------------------
 93	// Mock ProjectManager
 94	// ---------------------------------------------------------------------------
 95	
 96	class MockProjectManager {
 97	    private readonly data = new Map<string, ProjectData>();
 98	
 99	    /**
100	     * Seeds a project entry so the mock returns it from `getById`.

101	     */
102	    seed(project: ProjectData): void {
103	        this.data.set(project.Id, project);
104	    }
105	
106	    getById(id: string): ProjectData | undefined {
107	        return this.data.get(id);
108	    }
109	}
