115	function buildSut(projectsFolder: string): {
116	    router: Router;
117	    wm: MockWorkspaceManager;
118	    pm: MockProjectManager;
119	} {
120	    const router = new Router();
121	    const wm = new MockWorkspaceManager();
122	    const pm = new MockProjectManager();
123	    const stubOrchestrator = {} as never;
124	    const appConfig = { projectsFolder } as never;
125	    // Minimal ErrorLogManager stub — list() returns empty so no credential-missing
126	    // issues appear in these structural health check tests.
127	    const stubErrorLogManager = {
128	        list: () => ({ entries: [], total: 0 }),
129	        append: () => undefined,
130	        getById: () => undefined,
131	        clear: () => {},
132	        sources: () => [],
133	    } as never;
134	    registerWorkspaceRoutes(router, wm as never, stubOrchestrator, appConfig, pm as never, stubErrorLogManager);
135	    return { router, wm, pm };
136	}
